SELECT DATE_TRUNC('MONTH', s.started_at) AS started_month, YEAR(s.started_at) AS started_year, AVG(we.duration_sec) AS avg_duration_sec, MIN(we.duration_sec) AS min_duration_sec FROM web_events we LEFT JOIN sessions s ON we.session_id = s.id WHERE s.country = 'DE' GROUP BY DATE_TRUNC('MONTH', s.started_at), YEAR(s.started_at) HAVING min_duration_sec > 470 ORDER BY avg_duration_sec
